#include <iostream>

class Medida {
public:
    explicit Medida(int numero) : numero_{numero} {}
    int numero() const noexcept { return numero_; }
    void sustituir(int nuevo) noexcept { numero_ = nuevo; }
private:
    int numero_;
};
class MedidaIdentificada : public Medida {
public:
    MedidaIdentificada(int numero, int codigo) : Medida{numero}, codigo_{codigo} {}
    MedidaIdentificada(const MedidaIdentificada&) = default;
    MedidaIdentificada& operator=(const MedidaIdentificada& otro) noexcept;
    int codigo() const noexcept { return codigo_; }
private:
    int codigo_;
};
Medida capturar_base(const Medida& origen) {
    // Devuelve una Medida independiente con el numero de origen.
    (void)origen;
    return Medida{0};
}
MedidaIdentificada& MedidaIdentificada::operator=(const MedidaIdentificada& otro) noexcept {
    // Asigna ambas partes y devuelve una referencia a este destino.
    (void)otro;
    return *this;
}
void mostrar(const MedidaIdentificada& dato) {
    std::cout << '(' << dato.numero() << ',' << dato.codigo() << ')';
}
int main() {
    int numero_origen = 0, codigo_origen = 0, numero_destino = 0, codigo_destino = 0, nuevo = 0;
    if (!(std::cin >> numero_origen >> codigo_origen >> numero_destino >> codigo_destino >> nuevo)) {
        return 1;
    }
    MedidaIdentificada origen{numero_origen, codigo_origen}, destino{numero_destino, codigo_destino};
    const MedidaIdentificada& fuente = origen;
    const Medida& vista_destino = destino;
    Medida copia = capturar_base(fuente);
    const Medida* base_origen = &origen;
    std::cout << "InicioOrigen:";
    mostrar(origen);
    std::cout << ";InicioDestino:";
    mostrar(destino);
    std::cout << "\nCopiaBase:" << copia.numero() << ";Distinta:" << (&copia != base_origen) << '\n';
    MedidaIdentificada& retorno = (destino = fuente);
    std::cout << "Asignada:";
    mostrar(destino);
    std::cout << ";Origen:";
    mostrar(origen);
    std::cout << ";Retorno:" << (&retorno == &destino) << '\n';
    origen.sustituir(nuevo);
    std::cout << "ModificadaFuente:";
    mostrar(origen);
    std::cout << ";Destino:";
    mostrar(destino);
    std::cout << ";VistaDestino:" << vista_destino.numero() << ";CopiaBase:" << copia.numero() << '\n';
    const MedidaIdentificada& propio = destino;
    MedidaIdentificada& auto_retorno = (destino = propio);
    std::cout << "Autoasignada:";
    mostrar(destino);
    std::cout << ";Retorno:" << (&auto_retorno == &destino);
    return 0;
}

